  Skill_119763_AwakerSkillBackgroundStory = {
    Text = "Elle est arrogante. Elle cache le vide irréparable de son cœur sous son arrogance.\nElle a oublié qui elle était, elle a oublié qui elle devait être.\nDes milliers de croyants se prosternent à ses pieds, tandis qu'elle, dans les échos de la vénération, a oublié la chose la plus importante —\nelle s'est déjà soumise à ce destin pâle."
  },
  Skill_119763_BattleDesc = {
    Text = "Gagnez 2 points d'arithmetica, tirez 2 cartes. Au début du prochain tour, subissez [Arg3] points de <SacrificeKeyWord:sacrifice>. <RippleKeywords:Réplica> : retirez [Arg4] points de <SacrificeKeyWord:sacrifice>."
  },
  Skill_119763_Desc = {
    Text = "Obtenez 2 points d'arithmetica, tirez 2 cartes. Au début du prochain tour, subissez un <SacrificeKeyWord:sacrifice> égal à [Arg1] % de vos PV max. <RippleKeywords:Réplica> : retirez un <SacrificeKeyWord:sacrifice> égal à [Float:Arg2] % de vos PV max."
  },
  Skill_119763_EffectNameList = {
    Text = "Retirer le ratio de sacrifice"
  },
  Skill_119763_Name = {
    Text = "Chant des abysses"
  },
  Skill_119763_PropertyNameList = {
    Text = "$GrowValue1%"
  },
  Skill_119764_AwakerSkillBackgroundStory = {
    Text = "L'origine de la statue en ivoire dans les mains de Murphy fait l'objet de nombreuses spéculations. \n Certains disent que la statue provient des ruines sous-marines explorées sous l'indication de Murphy, tandis que d'autres affirment qu'elle est née du cœur qui palpite dans sa poitrine avec l'Enfant Saint. \n Mais il ne fait aucun doute que cette statue, symbole de son lien complexe avec la ville de Schraubverschwinden, silencieuse au fond de la mer de l'ignorance, est apparue dans le champ de vision des Marins le jour où Murphy est devenue « la véritable Mère divine ». \n Par la suite, les fidèles ont également été témoins de Murphy utilisant cette statue en ivoire pour briser les tempêtes et couper à travers la mer de sang. \n Le pouvoir absolu ne se limite souvent pas à un symbole illusoire. Les genoux de l'humanité ne s'inclinent que devant l'autorité de la force absolue."
  },
  Skill_119764_BattleDesc = {
    Text = "Obtenez <Block:[Block:Arg1]> points de bouclier, au début du prochain tour, subissez [Arg7] points de <SacrificeKeyWord:sacrifice>. Appliquez [Arg3] couches de <DwmofeiKeywords:rituel de descente> à tous les ennemis, infligez [Arg4] fois <Damage:[Damage:Arg5]> points de dommages à l'ennemi avec le plus de PV, bénéficiant d'un bonus de [Arg6]% de <TentacleInjurieIconKeywords:dégâts de tentacule>."
  },
  Skill_119764_Desc = {
    Text = "Obtenez <Block:[Block:Arg1]> points de bouclier, subissez un <SacrificeKeyWord:sacrifice> égal à [Arg2]% de votre PV Max au début du prochain tour. Appliquez [Arg3] couches de <DwmofeiKeywords:rituel de descente> à tous les ennemis, infligez [Arg4] fois <Damage:[Damage:Arg5]> points de dommages à l'ennemi avec le plus de vie, bénéficiant d'un bonus de [Arg6]% de <TentacleInjurieIconKeywords:dégâts des tentacules>."
  },
  Skill_119764_EffectNameList = {
    Text = "Bouclier, charges du rituel de descente, dommages, bonus de dégâts des tentacules"
  },
  Skill_119764_Name = {
    Text = "Princesse Illusoire"
  },
  Skill_119764_OverLimitUtlSkillDesc = {
    Text = "Obtenez <Block:[Block:Arg1]> points de bouclier, subissez [Arg7] points de <SacrificeKeyWord:sacrifice> au début du prochain tour. Appliquez [Arg8] couches de <DwmofeiKeywords:rituel de descente> à tous les ennemis, infligez [Arg4] fois <Damage:[Damage:Arg5]> points de dommages au ennemi ayant le plus de PV, bénéficiant d'un bonus de [Arg6] % <TentacleInjurieIconKeywords:dégâts des tentacules>. Placez 3 Arithmetica de coût 2 « Danse Circulaire de Luo Yan » dans votre main et donnez-lui <DepleteIconKeywords:consommation> et <PrepareKeypvewords1:préparez1>."
  },
  Skill_119764_PropertyNameList = {
    Text = "Défense *GrowValue1, $GrowValue2, Attaque *GrowValue3, $GrowValue4％"
  },
  Skill_119765_AwakerSkillBackgroundStory = {
    Text = "Elle est légère. Elle utilise sa légèreté pour lutter contre une réalité brisée. \nDansons, dit-elle, dansons une danse dédiée aux dieux. \nMerci aux dieux de nous avoir offerts une causalité inversée, un passé désordonné et un avenir insaisissable. \nSous les projecteurs, elle est le seul point de focalisation de tout."
  },
  Skill_119765_BattleDesc = {
    Text = "Obtenez <Posse:[Arg7]> points de fragment de clé. Selon la posture de tentacule, obtenez différents effets : « Marée Montante » : <TentacleInjurieIconKeywords:Dégâts des tentacules> +[TentaclePower:Arg1], générez 1 tentacule. « Océan Calme » : obtenez <Block:[Block:Arg2]> points de bouclier, le bouclier est conservé à 50 % jusqu'au tour suivant. « Vagues Déchaînées » : infligez [Arg3] fois <Damage:[Damage:Arg4]> points de dégâts au plus haut ennemi, bénéficiant d'un bonus de [Arg5] % de <TentacleInjurieIconKeywords:dégâts de tentacule>."
  },
  Skill_119765_Desc = {
    Text = "Obtenez [Arg6]% de régénération de Fragment de clé. Selon la posture de tentacule, obtenez différents effets : « Marée Montante » : <TentacleInjurieIconKeywords:dégâts de tentacule> +[TentaclePower:Arg8], générez 1 tentacule. « Océan Calme » : obtenez <Block:[Block:Arg9]> points de bouclier, le bouclier conservé à 50% jusqu'au tour suivant. « Vagues Déchaînées » : infligez [Arg3] fois <Damage:[Damage:Arg4]> points de dégâts à l'ennemi avec le plus de PV, bénéficiant d'un bonus de [Arg5]% de <TentacleInjurieIconKeywords:dégâts de tentacule>."
  },
  Skill_119765_EffectNameList = {
    Text = "Dégâts des tentacules, bouclier, dommages, bonus de dégâts des tentacules, efficacité de régénération de Fragment de clé"
