  Skill_119766_AwakerSkillBackgroundStory = {
    Text = "Elle a fait couler le sang ombilical divin dans la mer. Elle prie le dieu pour un voyage qui n'atteindra jamais sa destination.\n Tant que les bulles de rêves persistent, elle est la seule Mère divine."
  },
  Skill_119766_Desc_0 = {
    Text = "Murphy : Égarée obtient <Energy:[Energy:Arg1]> points de fureur. <ExaltIconKeywords:Éveiller> : Les dégâts infligés par Murphy : Égarée ajoutent [Arg2] % de <SacrificeKeyWord:Sacrifice>. Au début du tour, obtenez 1 niveau de <MingqiKeywords:Contrat du Destin>."
