  Skill_125372_Name_1 = {
    Text = "Soie sans limite"
  },
  Skill_125373_AwakerSkillBackgroundStory = {
    Text = "Pourquoi les inciter ? Ils sont déjà impuissants à résister. \n Pourquoi les inciter ? Jusqu'à ce que plus élevé et plus large, le tourbillon du désir de pouvoir englobe tout ce qui est visible. \n Parce que l'essence mondaine piégée dans l'émotion est difficile à avaler. Parce que le corps non assaisonné de l'ordinaire est totalement ennuyeux. \n La Terre sans Rêve est la récompense du prédateur avec des miettes pour sa proie. \n Au centre de la joie, il n'y a rien, seulement un chaos sans fin et une splendeur trompeuse sans fin."
  },
  Skill_125373_Desc_0 = {
    Text = "Xu obtient <Energy:[Energy:Arg1]> points de Fureur. <ExaltIconKeywords:Éveiller> : La première fois que chaque type de Carte d'instruction de Xu déclenche l'effet de <ResonanceKeywords:Résonance> par tour, son Coût d'Arithmetica de base devient 0."
  },
  Skill_125373_Desc_15 = {
    Text = "Xu obtient <Energy:[Energy:Arg1]> points de Fureur. <ExaltIconKeywords:Éveiller> : La première fois que chaque type de Carte d'instruction de Xu déclenche l'effet de <ResonanceKeywords:Résonance> par tour, son Coût d'Arithmetica de base devient 0. La limite d'accumulation de <WitherKeywords0:Ivresse> est portée à 15 couches, la première Carte d'instruction jouée par Xu chaque tour prend effet 1 fois supplémentaire."
