  },
  Skill_130929_AwakerSkillBackgroundStory = {
    Text = "Agitant joyeusement le terrible gros canon, sautillant sur le champ de bataille. \n Peu importe les soucis, peu importe le danger, car tout cela est si insignifiant comparé à des amis. \n « Ami, problème ! Mosk, fais ton entrée ! »"
  },
  Skill_130929_BattleDesc_0 = {
    Text = "Mosk obtient <Energy:[Energy:Arg1]> points de fureur. <ExaltIconKeywords:Éveiller> : Piochez 1 carte « Charge ! ». Après avoir libéré la poursuite, la prochaine explosion de fureur de Mosk bénéficie d'un bonus de dégâts des tentacules de +[Arg2]%, cumulable jusqu'à [Arg3] fois."
  },
  Skill_130929_BattleDesc_15 = {
    Text = "Mosk gagne <Energy:[Energy:Arg1]> Fureur. <ExaltIconKeywords:Éveiller> : Pioche 1 «Charge». Après que Mosk déclenche une Chasse, sa prochaine Exaltation gagne un Bonus de dégâts des tentacules supplémentaire de [Arg2]%, et la prochaine Exaltation inflige des <RealDamage:Dégâts Fixes> égaux à [Arg4]% des PV Max à l'ennemi ayant le plus de PV, cumulable jusqu'à [Arg3] <plural value=\"[Arg3]\" singular=\"fois\" plural=\"fois\">."
  },
  Skill_130929_Desc_0 = {
    Text = "Mosk gagne [Arg5]% Aliemus de base. <ExaltIconKeywords:Éveil> : Pioche 1 « Charge ». Après que Mosk Lâche une Chasse, la prochaine Exaltation Aliemus de Mosk gagne en plus [Arg2]% de Bonus de dégâts des tentacules, cumulable jusqu'à [Arg3] fois."
  },
  Skill_130929_Desc_15 = {
    Text = "Mosk gagne une Fureur égale à [Arg5]% de sa Fureur de Base. <ExaltIconKeywords:Éveiller> : Pioche 1 «Charge». Après que Mosk déclenche une Chasse, sa prochaine Exaltation gagne un Bonus de dégâts des tentacules supplémentaire de [Arg2]%, et la prochaine Exaltation inflige des <RealDamage:Dégâts Fixes> égaux à [Arg4]% des PV Max à l'ennemi ayant le plus de PV, cumulable jusqu'à [Arg3] <plural value=\"[Arg3]\" singular=\"fois\" plural=\"fois\">."
  },
