  Skill_131856_AwakerSkillBackgroundStory = {
    Text = "Les yeux, les oreilles, la langue, la peau, le cerveau — des sensations qui se répandent à travers tout le corps.\nL'amour et la tendresse partagés t'entoureront à jamais, jusqu'à la mort —"
  },
  Skill_131856_BattleDesc_0 = {
    Text = "Saya gagne <Energy:[Energy:Arg1]> points d'Aliemus. <ExaltIconKeywords:Éveiller> : Après avoir utilisé «Forge Écarlate», ajoute <ErosionColorInkKeywords:Distorsion de Perception> aux Cartes d'instruction des autres Corps éveillés présents ne possédant pas «<DestructionKeywords:Détruire>». Les 3 premières fois par tour où une Carte d'instruction portant <ErosionColorInkKeywords:Distorsion de Perception> est jouée, Saya et le Corps éveillé auquel appartient cette Carte d'instruction gagnent <Energy:[Energy:Arg2]> points d'Aliemus."
  },
  Skill_131856_BattleDesc_15 = {
    Text = "Saya obtient <Energy:[Energy:Arg1]> point(s) d'Aliemus. <ExaltIconKeywords:Éveiller> : Après avoir joué «Forge Écarlate», Saya obtient <Energy:[Energy:Arg4]> point(s) d'Aliemus et 1 couche de <KaiHuajishu:Gynécée>, et attache <ErosionColorInkKeywords:Distorsion de Perception> aux Cartes d'instruction des autres Corps éveillés présents qui ne possèdent pas «<DestructionKeywords:Détruire>». Les 3 premières fois par tour où une Carte d'instruction portant <ErosionColorInkKeywords:Distorsion de Perception> est jouée, Saya et le Corps éveillé auquel appartient cette Carte d'instruction obtiennent <Energy:[Energy:Arg2]> point(s) d'Aliemus."
  },
  Skill_131856_Desc_0 = {
    Text = "Saya obtient [Arg3]% d'Aliemus de base. <ExaltIconKeywords:Éveiller> : Après avoir utilisé « Forge Écarlate », confère <ErosionColorInkKeywords:Distorsion de Perception> aux Cartes d'instruction des autres Corps éveillés ne possédant pas « <DestructionKeywords:Détruire> ». Les 3 premières fois par tour qu'une carte avec <ErosionColorInkKeywords:Distorsion de Perception> est jouée, Saya et le Corps éveillé à qui appartient la carte obtiennent <Energy:[Energy:Arg2]> points d'Aliemus."
  },
  Skill_131856_Desc_15 = {
    Text = "Saya obtient [Arg3]% d'Aliemus de base. <ExaltIconKeywords:Éveiller> : Après avoir joué «Forge Écarlate», Saya obtient <Energy:[Energy:Arg4]> points d'Aliemus et 1 couche de <KaiHuajishu:Gynécée>, et ajoute <ErosionColorInkKeywords:Distorsion de Perception> aux Cartes d'instruction des autres Corps éveillés présents ne possédant pas «<DestructionKeywords:Détruire>». Les 3 premières fois par tour où une Carte d'instruction avec <ErosionColorInkKeywords:Distorsion de Perception> est jouée, Saya et le Corps éveillé auquel appartient cette Carte d'instruction obtiennent <Energy:[Energy:Arg2]> points d'Aliemus."
  },
