  Skill_131857_AwakerSkillBackgroundStory = {
    Text = "Avant d'atteindre ce monde tant recherché, ce monde où il n'est plus nécessaire de se cacher.\nTout ce qui se dresse sur le chemin est un «ennemi» qui doit être abattu."
  },
  Skill_131857_BattleDesc_0 = {
    Text = "Causes <Damage:[Damage:Arg1]> points de dégâts. Gagne <Energy:[Energy:Arg2]> points de folie"
  },
  Skill_131857_BattleDesc_2 = {
