  Skill_132428_Desc_0 = {
    Text = "Aurita obtient <Energy:[Energy:Arg1]> points de fureur.<ExaltIconKeywords:Éveiller> : obtient 1 tentacule et place 2 cartes «Division glandulaire» dans sa main. Lorsque Aurita inflige des dommages, [Arg2] tentacules attaquent 1 fois."
  },
  Skill_132428_Desc_15 = {
    Text = "Aurita obtient <Energy:[Energy:Arg1]> aliemus. <ExaltIconKeywords:Réveillez>: Gagnez 1 Tentacule, et ajoutez 2 \"Division de Glande\" dans votre main. Lorsque Aurita inflige des dégâts, faites attaquer [Arg2] Tentacules une fois. La \"frappe\" d'Aurita inflige des dégâts perforants et attaque +2 fois."
  },
  Skill_132428_EffectNameList = {Text = "Fureur"},
  Skill_132428_Name = {
    Text = "Test·Éveil"
  },
  Skill_132429_AwakerSkillBackgroundStory = {
    Text = "L'océan est profond et paisible, il porte le désir de vivre et la peur de la mort. \n Pourtant, il y a des gens qui veulent remplir la mer de rires et de jeux—quand Aurita lance une telle invitation, le sentiment de « pourquoi ne pas s'amuser avec elle » surgit toujours, laissant la simple joie envahir la poitrine."
  },
  Skill_132429_Desc_0 = {
    Text = "Inflige <Damage:[Damage:Arg1]> points de dégâts. Consommer jusqu'à 10 cartes « Division glandulaire » de la pioche et de la défausse, chaque carte infligeant 1 point de dégâts supplémentaire. Placez 2 cartes « Division glandulaire » dans votre main. Augmentez les dégâts infligés par « Aurita » dans ce combat de [Arg2] points."
  },
  Skill_132429_Desc_2 = {
    Text = "Inflige <Damage:[Damage:Arg1]> points de <PunctureDamagewords:Dégâts Perçants>. Consommez jusqu'à 10 cartes « Division glandulaire » de la pioche et de la pile de défausse, chaque carte infligeant 1 dégât supplémentaire. Placez 2 cartes « Division glandulaire » dans votre main. Augmentez les dégâts infligés par « Aurita » de [Arg2] points pour le reste de ce combat."
  },
