  Skill_142695_AwakerSkillBackgroundStory = {
    Text = "Il a conservé les parts les plus vives et attachantes de tous ses proches, et infligé aux ennemis les supplices les plus atroces et interminables.\nChaque nuit de festivités, il sombrait en riant dans un océan de coquilles vides."
  },
  Skill_142695_BattleDesc = {
    Text = "Supprime l'État <ExhaustionIconKeywords:Force réduite> propre. Réduit temporairement la <ExhaustionIconKeywords:Force> de tous les ennemis de [Exhaustion:Arg1] points. Inflige des <RealDamage:Dégâts Fixes> ( [Arg3] ) équivalents à [Arg2]% des Dégâts des tentacules à l'ennemi ayant le moins de PV ; si cela l'élimine, génère définitivement 1 carte <Nightmare:Thrall-Décharné><DerivativeCardKeywords_145:><DerivativeCardKeywords_146:><DerivativeCardKeywords_147:> dans la Main, au maximum 3 <Nightmare:Thrall-Décharnés> générés définitivement par combat."
  },
  Skill_142695_Desc = {
    Text = "Supprime son propre état <ExhaustionIconKeywords:Force réduite>. La <ExhaustionIconKeywords:Force> de tous les ennemis –[Exhaustion:Arg8] temporairement. Inflige des <RealDamage:Dégâts Fixes> égaux à [Arg2]% des Dégâts des tentacules à l'ennemi ayant le moins de PV. Si cela élimine la cible, génère 1 «Thrall-Décharné» permanent<DerivativeCardKeywords_145:><DerivativeCardKeywords_146:><DerivativeCardKeywords_147:> dans la main. Maximum 3 «Thrall-Décharnés» permanents générés par combat."
  },
  Skill_142695_EffectNameList = {
    Text = "Réduction Temporaire de Force, Bonus de dégâts des tentacules, Niveau Thrall-Décharné"
  },
  Skill_142695_Name = {Text = "Exaltation"},
  Skill_142695_OverLimitUtlSkillDesc = {
    Text = "Supprime l'État <ExhaustionIconKeywords:Force réduite> propre. Réduit temporairement la <ExhaustionIconKeywords:Force> de tous les ennemis de [Exhaustion:Arg1] points. Inflige à l'ennemi avec le moins de PV des <RealDamage:Dégâts Fixes> ( [Arg7] ) équivalant à [Arg6]% des Dégâts des tentacules ; si celui-ci est éliminé, générer définitivement 2 cartes <Nightmare:Thrall-Décharnés><DerivativeCardKeywords_145:><DerivativeCardKeywords_146:><DerivativeCardKeywords_147:> dans la main, maximum 3 <Nightmare:Thrall-Décharnés> générés définitivement par combat. Réduit le Coût d'Arithmetica de tous les <Nightmare:Thrall-Décharnés> de -1."
  },
  Skill_142695_PropertyNameList = {
