  Skill_142846_AwakerSkillBackgroundStory = {
    Text = "L'oreille humaine et les Technologies Silvercore actuelles sont pour l'instant incapables d'extraire la moindre information utile du sifflet de chasse de Pontos.\nPourtant, tous les individus assimilés par Ebwynnos semblent s'être très rapidement adaptés à suivre les instructions du Sifflet."
  },
  Skill_142846_Desc = {
    Text = "Si c'est la première utilisation de ce combat, génère 3 types différents de <Nightmare:Thrall-Décharnés><DerivativeCardKeywords_145:><DerivativeCardKeywords_146:><DerivativeCardKeywords_147:> et les place en main et obtient <Block:[Block:Arg1]> points de Bouclier ; pour chaque 4 Thrall-Décharnés permanents possédés, l'un d'eux est amélioré en « Jumelage de Décharnés » ; sinon, pioche 3 cartes <Nightmare:Thrall-Décharné>."
  },
