  Skill_144438_Desc_1 = {
    Text = "<PVPWeaponKeywords:Roue du Destin> : Quand un allié meurt, gagne <Energy:[Energy:Arg1]> Fureur. Quand un allié bénéficie d'une Renaissance, il gagne <Energy:[Energy:Arg2]> Fureur. L'effet de gain de Fureur ne s'active que si la Fureur de la cible n'est pas pleine, jusqu'à [Arg8] fois. Une fois le compteur épuisé, Détruit cette Roue du Destin."
  },
  Skill_144438_Name_1 = {
    Text = "Synchronisation des Âmes"
  },
  Skill_144486_AwakerSkillBackgroundStory = {
    Text = "La fée et le magicien se croisèrent sur un bout de terrain désolé, dans un recoin d'une petite ville.\nElle souriait et faisait signe à des enfants étrangers bien habillés, tandis que le magicien avait les yeux rivés sur le bracelet en or tintinnabulant au poignet de leur mère.\nLeurs regards se croisèrent dans les airs, et en un instant, chacun comprit les intentions de l'autre.\nDans ce duel silencieux, le magicien se révéla le plus habile, remportant une victoire étroite grâce à sa longue expérience.\nAinsi se leva le rideau d'une toute nouvelle et magnifique entreprise d'escroquerie et d'arnaque."
  },
  Skill_144486_BattleDesc_0 = {
