  Skill_144491_AwakerSkillBackgroundStory = {
    Text = "La cupidité est la vraie couleur de la nature humaine.\nNul ne peut résister à la tentation du sucre, pas même la Fée Marraine en personne.\nCaraboo sourit largement, dévoilant une rangée de dents pointues d'un noir de jais."
  },
  Skill_144491_BattleDesc_0 = {
    Text = "Caraboo gagne <Energy:[Energy:Arg1]> Fureur. <ExaltIconKeywords:Éveil> : Après avoir utilisé « Forge Écarlate », la prochaine <DerivativeCardKeywords_160:« Bénédiction Miraculeuse »> coûte -3 Arithmetica, et chaque option de <FaxianKeywords:découverte> est améliorée en un ensemble contenant 1 carte <DerivativeCardKeywords_152:« Bénédiction »> supplémentaire. Choisissez 1 ensemble à mélanger dans votre Pioche."
  },
  Skill_144491_BattleDesc_15 = {
    Text = "Caraboo gagne <Energy:[Energy:Arg1]> Fureur. <ExaltIconKeywords:Éveil> : Après avoir utilisé « Forge Écarlate », la prochaine <DerivativeCardKeywords_160:« Bénédiction Miraculeuse »> coûte -3 Arithmetica, et chaque option de <FaxianKeywords:découverte> est améliorée en un ensemble contenant 2 cartes <DerivativeCardKeywords_152:« Bénédiction »> supplémentaires. Choisissez 1 ensemble à mélanger dans votre Pioche. Après avoir joué une carte « Bénédiction », Fusion d'Embryon +10. Cet effet de fusion augmente en fonction de vos Points de vie perdus, jusqu'à +100%."
  },
  Skill_144491_Desc_0 = {
    Text = "Caraboo gagne [Arg2]% de Fureur de base. <ExaltIconKeywords:Éveil> : Après avoir utilisé « Forge Écarlate », la prochaine <DerivativeCardKeywords_160:« Bénédiction Miraculeuse »> coûte -3 Arithmetica, et chaque option de <FaxianKeywords:découverte> est améliorée en un ensemble contenant 1 carte <DerivativeCardKeywords_152:« Bénédiction »> supplémentaire. Choisissez 1 ensemble à mélanger dans votre Pioche."
  },
  Skill_144491_Desc_15 = {
    Text = "Caraboo gagne [Arg2]% de Fureur de base. <ExaltIconKeywords:Éveil> : Après avoir utilisé « Forge Écarlate », la prochaine <DerivativeCardKeywords_160:« Bénédiction Miraculeuse »> coûte -3 Arithmetica, et chaque option de <FaxianKeywords:découverte> est améliorée en un ensemble contenant 2 cartes <DerivativeCardKeywords_152:« Bénédiction »> supplémentaires. Choisissez 1 ensemble à mélanger dans votre Pioche. Après avoir joué une carte <Blessing:Bénédiction>, Fusion d'Embryon +10. Cet effet de fusion augmente en fonction de vos Points de vie perdus, jusqu'à +100%."
  },
