  Skill_145675_AwakerSkillBackgroundStory = {
    Text = "En vérité, Ogier avait depuis longtemps oublié le vrai visage de ce château.\nMais désormais, il pouvait s'appuyer sur les vœux enfouis dans son cœur pour ériger de nouvelles murailles.\nSi, sous sa protection, il pouvait encore entendre les rires et les joies des gens, et que les fleurs familières recouvraient à nouveau les prairies...\nAlors ce cœur, depuis longtemps transformé, aurait encore une raison de demeurer en ce monde."
  },
  Skill_145675_BattleDesc_0 = {
    Text = "Obtient <Block:[Block:Arg1]> points de Bouclier, obtient [Power:Arg2] points de <PowerIconKeywords:Force>, consomme toutes les <KuangNu:Marées Sombres>, chaque couche consommée augmente le Bouclier et la Force infligés de 33%, obtient 1 couche de <ShuZui:Autopunition>."
  },
  Skill_145675_BattleDesc_3 = {
    Text = "Obtient <Block:[Block:Arg1]> points de Bouclier, obtient [Power:Arg2] points de <PowerIconKeywords:Force>, consomme toutes les <KuangNu2:Marées Sombres>, chaque couche consommée augmente le Bouclier et la Force infligés de 50%, obtient 1 couche de <ShuZui:Autopunition>."
  },
  Skill_145675_Desc_0 = {
    Text = "Obtient <Block:[Block:Arg3]> points de Bouclier, obtient [Power:Arg4] points de <PowerIconKeywords:Force>, consomme toutes les <KuangNu:Marées Sombres>, chaque couche consommée augmente le Bouclier et la Force infligés de 33%, obtient 1 couche de <ShuZui:Autopunition>."
