  Skill_145675_OverLimitUtlSkillDesc_0 = {
    Text = "Obtient <Block:[Block:Arg1]> points de Bouclier, obtient [Power:Arg5] points de <PowerIconKeywords:Force>, consomme toutes les <KuangNu:Marées Sombres>, chaque couche consommée augmente le Bouclier et la Force infligés de 33%, obtient 1 couche de <ShuZui:Autopunition>."
  },
  Skill_145675_OverLimitUtlSkillDesc_3 = {
    Text = "Obtient <Block:[Block:Arg1]> points de Bouclier, obtient [Power:Arg5] points de <PowerIconKeywords:Force>, consomme toute la <KuangNu2:Marée Sombre>, chaque couche consommée augmente le Bouclier et la Force infligés de 50%, obtient 1 couche de <ShuZui:Péché Personnel>."
