  Skill_21615_AwakerSkillBackgroundStory = {
    Text = "Les souvenirs d'Ogier sont fragmentés à cause du phénomène d'érosion. \n Il se souvient des rires lors du bal, mais a oublié le nom du protagoniste du bal ; il se souvient de sa formation au sein de l'ordre des chevaliers, mais ne sait pas pourquoi le duc a fait de lui un chevalier si jeune ; il se souvient d'être tombé sous les griffes des chevaliers, mais ne peut pas se rappeler quel sourire il protégeait. \n Personne ne peut lui en vouloir, il a déjà accompli toutes les responsabilités qu'un chevalier doit assumer — y compris sacrifier sa vie pour la volonté de protéger."
  },
  Skill_21615_Desc_0 = {
    Text = "Dissipe <FragileIconKeywords:fragilité>. Gagne <Block:[Block:Arg1]> points de bouclier. Gagne [Power:Arg2] points de <PowerIconKeywords:force> temporaire"
  },
  Skill_21615_Desc_2 = {
    Text = "Si vous avez l'état <FragileIconKeywords:fragile>, dissipez-le et gagnez <Block:[Block:Arg3]> bouclier. Gagnez <Block:[Block:Arg1]> bouclier. Gagnez [Power:Arg2] de <PowerIconKeywords:force> temporaire"
  },
  Skill_21615_EffectNameList_0 = {
