  Skill_4154_AwakerSkillBackgroundStory = {
    Text = "Écoute, c'est le son du glas résonnant pour elle-même. \n Ce n'est pas une chercheuse folle, ni une perdue désespérée, elle a simplement choisi tranquillement son chemin vers la fin. \n Les pétales fanés dansent pour son rituel, le vent de mer en frénésie pleure pour son chant funèbre. \n Après ce son de cloche qui transperce le cœur, le monde tombe brièvement dans un silence mortel."
  },
  Skill_4154_Desc_0 = {
    Text = "Applique [Poison:Arg1] couches <IntoxicationIconKeywords:poison> à tous les ennemis, applique [Arg2] tours <WeaknessIconKeywords:faiblesse> et <VulnerabilityIconKeywords:vulnérable>"
