  Skill_4313_Name = {Text = "Toxine"},
  Skill_4314_AwakerSkillBackgroundStory = {
    Text = "Son sang est brûlant à cause d'eux, son cerveau bout à cause d'eux.\nPeu importe si ces enfants d'autres formes peuvent réaliser son vœu, peu importe qu'ils puissent subsister dans l'illusion.\nThais accueille chaque naissance d'un fils sacré avec amour"
  },
  Skill_4314_Desc_0 = {
    Text = "[<DevouredIconKeywords:Dévorer> : Faites gagner <Energy:[Energy:Arg1]> points de folie aux autres éveillés.] Infligez <Damage:[Damage:Arg2]> points de dommages à tous les ennemis, infligeant <BleedingIconKeywords:Saignement> à hauteur de [Arg3]% de dommages, et appliquez <IntoxicationIconKeywords:Poison> à hauteur de [Arg4]% de dommages, tout en obtenant <RetaliateIconKeywords:Contre-attaque> à hauteur de [Arg5]% de dommages. Choisissez 1 carte d'instruction non dérivée de votre main, et placez [Arg7] copies originales supplémentaires avec <DepleteIconKeywords:Consommation>, <NothingnessIconKeywords:Vide> et -[Arg6] coût d'Arithmetica dans votre main."
  },
  Skill_4314_EffectNameList = {
    Text = "Aliemus, dégâts, pourcentage de saignement, pourcentage de poison, pourcentage de contre-attaque"
  },
  Skill_4314_Name = {
    Text = "Cérémonie de l'Abondance"
  },
  Skill_4314_OverLimitUtlSkillDesc_0 = {
    Text = "[<DevouredIconKeywords:Dévorer> : faire gagner <Energy:[Energy:Arg1]> points d'Aliemus aux autres Corps éveillés.] Inflige <Damage:[Damage:Arg2]> points de Dommages à tous les ennemis, applique un <BleedingIconKeywords:Saignement> équivalant à [Arg3]% des Dommages, applique un <IntoxicationIconKeywords:Poison> équivalant à [Arg4]% des Dommages et obtient une <RetaliateIconKeywords:Contre-attaque> équivalant à [Arg5]% des Dommages. Choisissez 1 Carte d'instruction non dérivée dans votre main, placez [Arg7] Copies basiques avec <DepleteIconKeywords:Consommation> et <NothingnessIconKeywords:Vide> dans votre main, réduisant leur Coût d'Arithmetica de -[Arg6]. Durant les 3 prochains tours, au début de chaque tour, transforme 1 «Embryon» en «Fils de la sainteté» ; s'il n'y a pas d'«Embryon», la <EmbryoFusionIconKeywords:Fusion d'Embryon> +[Blood:Arg8], sans être affectée par l'effet d'amélioration de la Fusion d'Embryon."
  },
