  Skill_4315_Desc_0 = {
    Text = "Lily gagne <Energy:[Energy:Arg1]> points d'aliemus. <ExaltIconKeywords:réveil> : Au début du tour, obtient 10% de la santé maximum <PainWord:endurance>. Lorsqu'elle applique un bouclier, Lily applique [Poison:Arg2] couches <IntoxicationIconKeywords:poison> au meilleur ennemi en vie"
