  Skill_4403_AwakerSkillBackgroundStory = {
    Text = "D'innombrables engrenages s'entrelacent, se propulsant mutuellement, donnant à la coque en porcelaine la capacité d'imiter la vie.\nC'est son œuvre la plus fière, un instrument d'une finesse inégalable.\nErica n'aurait jamais imaginé que cet automate portant son nom deviendrait sa seconde vie"
  },
  Skill_4403_Desc_0 = {
    Text = "Erica obtient <Energy:[Energy:Arg1]> points de fureur. <ExaltIconKeywords:Éveiller> : lorsque Erica inflige des dommages, elle gagne [Power:Arg2] points de force temporaire ; lorsque Erica applique un bouclier, elle gagne [Arg3] points d'alerte temporaire."
  },
  Skill_4403_Desc_15 = {
    Text = "Erica obtient <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Éveiller> : Quand Erica inflige des Dommages, elle obtient [Power:Arg2] <PowerIconKeywords:FOR> Temporaire ; quand Erica applique un Bouclier du personnage, elle obtient [Arg3] <AlertIconKeywords:Alerte> Temporaire. Après qu'Erica a lancé une Exaltation, son Exaltation bénéficie en plus d'un bonus de 1x FOR et Alerte."
