  Skill_4407_AwakerSkillBackgroundStory = {
    Text = "Sa peau est verte, les vaisseaux sanguins pourris se tordent et s'enroulent sans cesse. \n Son épaule semble donner naissance à quelque chose — un liquide noir s'écoule le long de son bras, se propageant sur la table d'opération. \n La chair nouvellement née éclot de la plaie, se précipitant doucement et silencieusement. \n La jeune fille affaiblie affiche un sourire. \n « Enfin, nous nous revoyons, @2. »"
  },
  Skill_4407_Desc_0 = {
    Text = "Inflige aléatoirement <Damage:[Damage:Arg1]> de dégâts [Arg2] fois. Jusqu'au début du prochain tour, pour chaque 2 points de vie perdus, gagne 1 bouclier au début du prochain tour"
