  Skill_4421_AwakerSkillBackgroundStory = {
    Text = "Elle danse sous la lune croissante.\nLes bords de sa robe s'enroulent autour de ses bras, tournoyant sans cesse comme un nuage.\nSous elle, le grand lac qui s'écoule sans fin fusionne progressivement avec le ciel.\nDanse ! Danse ! dit la voix dans les ténèbres.\nRéveille ce grand adulte endormi, puis accomplis cette promesse millénaire."
  },
  Skill_4421_Desc_0 = {
    Text = "Karen obtient <Energy:[Energy:Arg1]> points de fureur. <ExaltIconKeywords:réveil> : après avoir joué une carte, Karen récupère <Heal:[Heal:Arg2]> points de PV et gagne <Energy:[Energy:Arg3]> points de fureur. Après avoir joué <DerivativeCardKeywords_42:«Cuisine merveilleuse»>, appliquez [Poison:Arg4] couches <IntoxicationIconKeywords:empoisonnement> à tous les ennemis."
  },
  Skill_4421_Desc_15 = {
    Text = "Karen obtient <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Éveiller> : Après que Karen joue une Carte, restaure <Heal:[Heal:Arg2]> PV et obtient <Energy:[Energy:Arg3]> Aliemus. En fin de tour, si la Carte d'instruction de Karen est Gardée, déclenche l'effet 2 fois supplémentaires. Après avoir joué <DerivativeCardKeywords_42:«Cuisine merveilleuse»>, inflige [Poison:Arg4] <plural value=\"[Poison:Arg4]\" singular=\"charge\" plural=\"charges\"> charges de <IntoxicationIconKeywords:Poison> à tous les ennemis."
