  Skill_4575_AwakerSkillBackgroundStory = {
    Text = "C'est une ancienne ruine faite de corail.\nAu départ, c'était juste une lueur blanche ondulant dans l'eau.\nPlus tard, elle a poussé des escaliers élevés, des reliefs tordus, des colonnes majestueuses…\nBang ! Quand tout s'est arrêté brusquement, l'art perdu a enfin levé le voile au fond de la mer.\nElle doit se rendre là où se trouve l'art."
  },
  Skill_4575_BattleDesc_0 = {
    Text = "Obtenez <Block:[Block:Arg1]> points de bouclier. Infligez <Damage:[Damage:Arg2]> points de dégâts à tous les ennemis, chaque point de bouclier augmente les dégâts de [Arg3] points, cette compétence bénéficie en plus d'un [Arg4]% de taux critique et de bonus de dégâts critiques. Dans un Combat de Chef, cette compétence inflige une attaque supplémentaire."
  },
  Skill_4575_BattleDesc_3 = {
