  Skill_4579_AwakerSkillBackgroundStory = {
    Text = "Le sorcier dit : « Les païens sont nombreux \n et nous, à Lévan, semblons faibles. \n Frère Uvhash, sonne de ta trompette, \n et combats comme un fou. » \n Le guerrier répondit : « Il n'y a pas de païens ici. \n Vous serez tous tués par moi, peu importe votre ethnie ou votre foi. \n À ce moment-là, les corps rempliront la vallée, couvriront les sommets, \n et ce sera mon offrande à l'Ode au Sang et à la Sable. »"
  },
  Skill_4579_BattleDesc_0 = {
    Text = "[<DevouredIconKeywords:Dévorer> : Les dégâts de « Ode au Sang et à la Sable » infligés lors des prochaines utilisations de ce combat augmentent de [Arg4] points, et le multiplicateur de force augmente de [Arg3] fois.] Inflige <Damage:[Damage:Arg1]> points de dégâts à tous les ennemis. <PowerIconKeywords:Force> a un effet de [Arg2] fois sur « Ode au Sang et à la Sable ». Uvhash gagne <Energy:[Energy:Arg5]> points de fureur."
  },
  Skill_4579_Desc_0 = {
    Text = "[<DevouredIconKeywords:Dévorer> : Les dégâts infligés par «Ode au Sang et à la Sable» augmentent de [Arg4] points, et le multiplicateur de force augmente de [Arg3] fois.] Inflige <Damage:[Damage:Arg1]> points de dégâts à tous les ennemis. <PowerIconKeywords:Force> a un effet multiplicatif de [Arg2] fois sur «Ode au Sang et à la Sable». Gagnez autant de fureur que 2 fois la charge de fureur d'Uvhash."
  },
  Skill_4579_EffectNameList = {
    Text = "Dégâts, augmentation des dégâts"
  },
  Skill_4579_Name = {
    Text = "Ode au Sang et à la Sable"
  },
  Skill_4579_OverLimitUtlSkillDesc = {
    Text = "[<DevouredIconKeywords:dévorer> : Les dégâts de « chant du sang et du sable » libérés ultérieurement dans ce combat augmentent de [Arg4] points, le multiplicateur de puissance augmente de [Arg3] fois.]Inflige <Damage:[Damage:Arg1]> points de dégâts à tous les ennemis. <PowerIconKeywords:pouvoir> exerce un effet de [Arg2] fois sur « chant du sang et du sable ». Uvhash reçoit <Energy:[Energy:Arg5]> points de folie. Remplit la main avec « hurlons, sang ! » ajoutant illusion et épuisement. Ce tour, les attaques d'Uvhash augmentent de 1"
  },
