  Skill_4615_AwakerSkillBackgroundStory = {
    Text = "Faint est défectueuse.\nFaint est dangereuse.\nFaint est maudite.\nFaint, est une couleur la plus mystérieuse et colorée des étoiles"
  },
  Skill_4615_BattleDesc_15 = {
    Text = "Faint gagne <Energy:[Energy:Arg1]> Fureur. <ExaltIconKeywords:Éveiller> : Vole <TouquKeywords:immédiatement et de façon permanente> [Arg4] <PowerIconKeywords:STR> à tous les ennemis. Gagne [Counterattack:Arg3] charge(s) de <RetaliateIconKeywords:Contre-attaque>. Le taux de déclin de la Résistance à la mort pour ce combat est réduit de 50% à 45%. Lorsque Faint joue une carte, <TouquKeywords:Vole> [Arg2] <PowerIconKeywords:STR> à tous les ennemis. En fin de tour, inflige des <RealDamage:Dégâts Fixes> égaux à 50% de la <RetaliateIconKeywords:Contre-attaque> de Faint."
  },
  Skill_4615_Desc_0 = {
    Text = "Faint gagne <Energy:[Energy:Arg1]> Fureur. <ExaltIconKeywords:Éveiller> : Gagne [Counterattack:Arg3] charges de <RetaliateIconKeywords:Compteur>. Le taux de décroissance de la Résistance à la mort est réduit de 50% à 45% durant ce combat. Quand Faint joue une carte, <TouquKeywords:Vole> [Arg2] <PowerIconKeywords:Force> à tous les ennemis. En fin de tour, inflige des <RealDamage:Dégâts Fixes> égaux à 50% du <RetaliateIconKeywords:Compteur> de Faint."
