  Skill_4660_AwakerSkillBackgroundStory = {
    Text = "Un, deux, un, deux... \n Elle tient un plateau et se faufile dans la foule en suivant un rythme léger. \n Les invités boivent et chantent sans arrêt, elle sert les plats et sourit sans relâche. \n Tout ici est doré. Une salle dorée, du vin doré, et la traîne dorée de sa robe. \n Karen aime le doré. Elle affiche son sourire emblématique, qu'elle a pratiqué des milliers de fois. \n « Bon appétit, cher client — !! »"
  },
  Skill_4660_Desc_0 = {
    Text = "Retirez <SlowIconKeywords:Slowness> de toutes les cartes en main. Restaurez <Heal:[Heal:Arg1]> points de Vie. Ajoutez 1 <DerivativeCardKeywords_42:\"Cuisine Merveilleuse\"> à votre main. Appliquez [Poison:Arg2] couches de <IntoxicationIconKeywords:Poison> à tous les ennemis."
