  Skill_4661_Name = {
    Text = "Vision tragique au miel"
  },
  Skill_4662_AwakerSkillBackgroundStory = {
    Text = "Les gens admirent sa beauté, envient son charme, mais personne ne prend un bouton de fleur au sérieux. \n Dans les champs, le bouton oscille, soumis au bon vouloir des autres et considéré comme un atout pour la promotion du jardinier. \n Ce n'est que lorsqu'elle s'épanouit devant la couronne que les gens réalisent qu'ils ont été piqués et saignés à blanc."
  },
  Skill_4662_BattleDesc_0 = {
    Text = "Inflige aléatoirement <Damage:[Damage:Arg1]> dégâts [Arg3] fois. À la fin du tour, restaure <Heal:[Heal:Arg2]> hp."
  },
  Skill_4662_BattleDesc_2 = {
    Text = "Inflige aléatoirement <Damage:[Damage:Arg1]> dégâts [Arg3] fois. Pour chaque dégât infligé, taux critique +5%. À la fin du tour, restaure <Heal:[Heal:Arg2]> hp."
