  Skill_4663_AwakerSkillBackgroundStory = {
    Text = "Des machines froides ont remplacé le cœur, et l'huile dans les tuyaux hydrauliques a remplacé le sang. Elle devrait être froide, rationnelle, et agir selon les ordres. \n Mais, une volonté étrangère se meut silencieusement dans son corps. Il n'a besoin ni de sang, ni de chaleur, il peut brûler d'une malveillance inhumaine par lui-même. Il dit : Soumets-toi, créature vile et faible, puis péris dans ma sphère électrique brûlante."
  },
  Skill_4663_BattleDesc_0 = {
    Text = "Obtenez [Power:Arg1] points de <PowerIconKeywords:force> temporaire. Gagnez <Posse:[Arg2]> points de fragment de clé. Dissipez votre état <WeaknessIconKeywords:faiblesse>. Chaque fois qu'une carte entre dans <DimensionalSpaceIconKeywords:espace hyperspatial>, se transforme en <DerivativeCardKeywords_14:« Arme Mécanique - Ramasser »>."
  },
  Skill_4663_BattleDesc_1 = {
    Text = "Obtenez [Power:Arg1] points de <PowerIconKeywords:force> temporaire. Gagnez <Posse:[Arg2]> points de fragment de clé. Dissipez votre état <WeaknessIconKeywords:faiblesse>. Ajoutez 1 carte « Erica » avec <DepleteIconKeywords:consommation> de type « Attaque » à votre main. Chaque fois qu'une carte entre dans <DimensionalSpaceIconKeywords:Espace Hyperspatial>, se transforme en <DerivativeCardKeywords_14:« Arme Mécanique - Ramasser »>."
  },
  Skill_4663_Desc_0 = {
    Text = "Obtenez [Power:Arg1] points de <PowerIconKeywords:force> temporaire. Obtenez une quantité d'énergie de clé argentée équivalente à la régénération de fragment de clé d'Erica. Dissipez votre propre état <WeaknessIconKeywords:faiblesse>. Chaque fois qu'une carte entre dans <DimensionalSpaceIconKeywords:Espace Hyperspatial>, se transforme en <DerivativeCardKeywords_14:« Arme Mécanique - Ramasser »>."
  },
  Skill_4663_Desc_1 = {
    Text = "Obtenez [Power:Arg1] points de <PowerIconKeywords:force> temporaire. Gagnez une quantité d'énergie en clé d'argent équivalente à la régénération de fragment de clé d'Erica. Dissipez votre état <WeaknessIconKeywords:faiblesse>. Ajoutez 1 carte « frappe » à votre main, avec <DepleteIconKeywords:consommation> attaché. Chaque fois qu'une carte entre dans <DimensionalSpaceIconKeywords:espace hyperspatial>, se transforme en <DerivativeCardKeywords_14:« Arme Mécanique - Recueillir »>."
