  Skill_4664_AwakerSkillBackgroundStory = {
    Text = "Une épidémie invisible s'installe silencieusement, apportant une douleur et une folie infinies. \n\n Le Fou ne peut dormir la nuit, accablé par son incapacité à soulager la souffrance des gens. \n\n « Ô créateur plein de miséricorde, sauve-les, je suis prêt à porter toute leur douleur et leur chagrin. » \n\n Alors le Père Dieu lui accorde une « bénédiction », lui permettant de prendre en main l'ardoise gravée de la Parole de Dieu, pour accomplir des actes de soulagement de la souffrance."
  },
  Skill_4664_Desc_0 = {
    Text = "Salvador gagne <Energy:[Energy:Arg1]> points de aliemus. <ExaltIconKeywords:réveil> : mettre une carte <B02AFKeyWord:l'amour c'est protéger> dans votre main. À la fin du tour, gagnez [Power:Arg2] points de <PowerIconKeywords:pouvoir>"
  },
  Skill_4664_Desc_15 = {
    Text = "Salvador gagne <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Éveil> : Place 1 <B02AFKeyWord:Protégé par la bienveillance> dans la main. En fin de tour, gagne [Power:Arg2] <PowerIconKeywords:FOR>. La Forge Écarlate accumulée par « Bénédiction du Créateur » et « Ossements bénis » +25%, et lorsque « Exorcisme » est sélectionné pour « Souffrance à dissiper », chaque 1% de PV Max consommé par la Forge Écarlate accorde +5% Dégâts Finaux."
  },
