  Skill_4667_AwakerSkillBackgroundStory = {
    Text = "C'est un immense labyrinthe qui transcende toutes les dimensions. \n Les voyageurs égarés dans le labyrinthe doivent faire face à un échange impoli. \n Si la réponse est « non », le voyageur sera piégé pour toujours dans le labyrinthe. \n Si la réponse est « oui », le voyageur sera implanté avec une progéniture profanante et toutes ses mémoires seront effacées. \n Quoi, tu demandes quel est le contenu spécifique de l'échange ? \n Personne ne sait quel est le contenu spécifique de l'échange, y compris le pâle Maître du labyrinthe. \n L'échange, c'est juste un échange."
  },
  Skill_4667_Desc_0 = {
    Text = "[<DevouredIconKeywords:Dévorer> : Gagne [Power:Arg1] points de <PowerIconKeywords:Pouvoir> et [Arg4] points d'<AlertIconKeywords:Alerte>.]Gagne <Block:[Block:Arg2]> points de bouclier. Inflige [Poison:Arg3] couches <IntoxicationIconKeywords:Poison> à tous les ennemis"
  },
  Skill_4667_EffectNameList = {
    Text = "Pouvoir,alerte,bouclier,poison"
  },
  Skill_4667_Name = {Text = "Abri Pâle"},
  Skill_4667_OverLimitUtlSkillDesc_0 = {
    Text = "[<DevouredIconKeywords:Dévorer> : Gagne [Power:Arg1] points de <PowerIconKeywords:Pouvoir> et [Arg4] points d'<AlertIconKeywords:Alerte>.]Gagne <Block:[Block:Arg2]> points de bouclier. Inflige [Poison:Arg3] couches <IntoxicationIconKeywords:Poison> à tous les ennemis. Piochez 2 cartes de commandement de défense non frappantes d'Agrippa, réduisez la consommation de calcul de 2 cartes de commandement de défense non frappantes d'Agrippa en main de -1 pour ce tour"
  },
  Skill_4667_PropertyNameList = {
    Text = "Puissance d'attaque*GrowValue1,Défense*GrowValue4,Défense*GrowValue2,Puissance d'attaque*GrowValue3"
  },
  Skill_4668_AwakerSkillBackgroundStory = {
    Text = "Il ne peut pas accepter qu'il ait failli mourir. Il devrait être indestructible, il devrait être inébranlable. Si le corps humain est un obstacle à son ascension vers le sommet de la force, alors il faut abandonner ce corps ; si abandonner ses semblables peut lui apporter la puissance, alors il enterrera son passé. \n Il jeta la grande lame dans les profondeurs de la mer, empruntant une force inhumaine, jurant de devenir le maître de tout. \n Même ceux qui lui ont donné de la force, leur avenir devra également se trouver à ses pieds."
  },
  Skill_4668_Desc = {
    Text = "Choisissez : <O06_AFKeyWord2:Usurper> ou <O06_AFKeyWord1:Récupérer>. Placez 3 <DerivativeCardKeywords_17:\"Pouvoir de la Grande Épée\"> dans votre main."
  },
  Skill_4668_EffectNameList = {
    Text = "Force Temporaire"
  },
  Skill_4668_Name = {
    Text = "Pouvoir des abysses"
  },
  Skill_4668_OverLimitUtlSkillDesc = {
    Text = "Sélectionnez : <O06_AFKeyWord1:usurpation> ou <O06_AFKeyWord2:hibernation>. Ajoutez 3 cartes <DerivativeCardKeywords_17:« La puissance de la lame géante »> à votre main. Lorsque vous choisissez « usurpation », les dégâts de base de « La puissance de la lame géante » ajoutée à votre main augmentent de 400%, et le coût d'Arithmetica devient 0. Lorsque vous choisissez « hibernation », ne placez pas « La puissance de la lame géante », mais ajoutez 2 cartes « Dégâts d'attaque critique » à votre main, et faites-les obtenir « Consommation », « Prépare 1 » et « Garder »."
  },
  Skill_4669_AwakerSkillBackgroundStory = {
    Text = "Elle était le porteur des émotions, la continuité des sentiments.\nLaissons cette encre sombre couler, laissons cette poésie être gaspillée.\nLes mots jamais dits dans ce monde commenceront avec son recueil de poèmes"
  },
  Skill_4669_Desc_0 = {
    Text = "Horla obtient <Energy:[Energy:Arg1]> points de fureur. <ExaltIconKeywords:Éveiller> : obtenez immédiatement 1 couche de métaphore <D06CardKeyWord1> pour toutes les émotions autres que l'émotion actuelle, et obtenez 1 couche au début de chaque tour, avec un maximum de 3 couches par <D06CardKeyWord1>. Chaque couche de <D06CardKeyWord1> consomme la métaphore correspondante lors du <TransitionIconKeywords:Saut Quantique> des poèmes et offre un bonus supplémentaire."
  },
  Skill_4669_Desc_15 = {
    Text = "Horla gagne <Energy:[Energy:Arg1]> points de Aliemus. <ExaltIconKeywords:Éveiller> : Obtient immédiatement 1 couche de <D06CardKeyWord1:Métaphore> d'une émotion autre que l'émotion actuelle, en obtient également 1 couche au début de chaque tour, avec un maximum de 3 couches par type de <D06CardKeyWord1:Métaphore>. Chaque couche de <D06CardKeyWord1:Métaphore> consomme la <D06CardKeyWord1:Métaphore> correspondante lors du <TransitionIconKeywords:Saut Quantique> du Poème et accorde un bonus supplémentaire. Après avoir déclenché l'Annihilation, la prochaine Carte d'instruction de Horla ce tour déclenche l'effet de Saut Quantique. Chaque fois que Horla consomme 3 couches ou plus de Métaphore, l'effet d'aura de l'émotion actuelle est temporairement augmenté de [Arg2]%, cet effet ne peut pas se cumuler."
  },
  Skill_4669_EffectNameList = {Text = "Fureur"},
  Skill_4669_Name = {
    Text = "Préface du recueil de poèmes"
  },
