  Skill_4694_AwakerSkillBackgroundStory = {
    Text = "Dans la sombre prison de Newgate, la cire omniprésente de Londinium est aussi une denrée précieuse. \n Puisqu'elle est rare, elle doit être utilisée à des moments cruciaux, par exemple lors du châtiment, sur la peau des enfants désobéissants. \n Ce n'est pas une cire spéciale, elle tombe avec des gémissements et des cris tragiques, mais aux oreilles de la jeune fille, cela ressemble à un poème élégant."
  },
  Skill_4694_BattleDesc_0 = {
    Text = "Obtenez [Counterattack:Arg2] niveaux de <RetaliateIconKeywords:Contre-attaque>. Réduisez temporairement la <PowerIconKeywords:force> de tous les ennemis de [Exhaustion:Arg1] points, chaque ennemi vous donne [Power:Arg1] points de <PowerIconKeywords:Force Temporaire>. Retirez tous les états <RetaliateIconKeywords:Contre-attaque> des ennemis."
  },
  Skill_4694_BattleDesc_2 = {
    Text = "Obtenez [Counterattack:Arg2] niveaux de <RetaliateIconKeywords:Contre-attaque>. Réduisez temporairement tous les ennemis de [Exhaustion:Arg1] points <ExhaustionIconKeywords:force>, chaque ennemi vous donne [Power:Arg1] points de <PowerIconKeywords:Force Temporaire>. Retirez tous les états <RetaliateIconKeywords:Contre-attaque> des ennemis. Obtenez <Energy:[Energy:Arg3]> points de fureur."
  },
  Skill_4694_Desc_0 = {
    Text = "Gagnez [Counterattack:Arg2] couches de <RetaliateIconKeywords:counter>. <TouquKeywords:steal> [Arg1] <PowerIconKeywords:str> de tous les ennemis et retirez leur état <RetaliateIconKeywords:counter>."
