  Skill_4750_AwakerSkillBackgroundStory = {
    Text = "Naissance, descendez, proliférez. \n Dans une réalité qui se dissout de plus en plus, dans un monde sombre qui s'approche, dans le vide qui s'apprête à renaître. \n Votre existence est le fruit du sacrifice de la mère, la cause de la survie de la mère. \n Ô fils de la sainteté, renaissez dans ce nouveau monde — dans ce monde pur, où toutes les peurs se sont évaporées, renaissez."
  },
  Skill_4750_Desc_0 = {
    Text = "Thais gagne <Energy:[Energy:Arg1]> points de folie. <ExaltIconKeywords:réveil> : obtenez immédiatement 1 carte <DerivativeCardKeywords_10:Fils de la sainteté>. Chaque fois que vous libérez un ordre de clé, transformez un embryon en <DerivativeCardKeywords_10:Fils de la sainteté>"
  },
  Skill_4750_Desc_15 = {
