  Skill_4770_AwakerSkillBackgroundStory = {
    Text = "Dans le salon de Sorel, la danse en rond avant la fin est un projet à garder. \n Sous l'invitation de l'alcool et des hormones, que ce soit le prince d'un pays voisin, un haut dignitaire de la cour ou une servante proche, tous se tiennent par la main pour plonger dans la piste de danse et s'enivrer de joie. \n La musique s'estompe, le salon se termine, et à part le pouvoir et la lueur de l'aube qui émerge à l'horizon, il ne reste rien près de Sorel."
  },
  Skill_4770_Desc_0 = {
    Text = "[<UnlimitedDevouredIconKeywords:Dévoration Infinie>: Le nombre de fois que les dommages de cette danse de la soif du pouvoir est augmenté de +[Arg3], régénération de PV +<Heal:[Heal:Arg6]>.] Inflige aléatoirement <Damage:[Damage:Arg2]> points de dommages [Arg1] fois. À la fin du tour, récupère <Heal:[Heal:Arg4]> points de vie."
  },
  Skill_4770_EffectNameList_0 = {
    Text = "Dégâts, récupération, récupération de dévoration infinie"
