  Skill_4822_AwakerSkillBackgroundStory = {
    Text = "Dans l'errance sans fin, Tinct a déjà oublié le nom de sa patrie.\nAu fil des longues années, l'univers a oublié le nom de cette planète morte.\nElle est, comme d'innombrables planètes fusionnées et abandonnées, désignée sous le nom de « planète désolée ». \nSa voix est peut-être le dernier écho de cette planète lointaine."
  },
  Skill_4822_Desc_0 = {
    Text = "Teinture obtient <Energy:[Energy:Arg1]> points d'aliemus, <ExaltIconKeywords:réveil>: augmente les dégâts de base de « coup » de Teinture de [Arg2]%, toutes les cartes de Teinture reçoivent 1 effet aléatoire qui sera supprimé à la fin de la bataille"
  },
  Skill_4822_Desc_15 = {
    Text = "Tinct gagne <Energy:[Energy:Arg1]> Aliemus, <ExaltIconKeywords:Éveil> : Le Dommage de base de l'« Attaque » de Tinct +[Arg2]%, toutes les cartes de Tinct gagnent 1 effet aléatoire, qui sera retiré à la fin du combat. La première fois que Tinct joue une « Compétence » à chaque tour, génère 1 « Attaque » Temporaire avec un Coût d'Arithmetica de 0, les effets aléatoires de cette « Attaque » x2."
