  Skill_59476_AwakerSkillBackgroundStory = {
    Text = "Avant d'entendre cette musique, tu n'avais jamais vraiment eu d'oreilles. Après l'avoir entendue, tu ne trouveras plus jamais un tel son. Alors concentre-toi, retiens ton souffle, et loue cette musique unique de toute une vie !"
