  Skill_59476_Desc_0 = {
    Text = "Hamelin obtient <Energy:[Energy:Arg1]> points de Fureur. <ExaltIconKeywords:Éveiller>: Au début du tour, ajoutez une carte « <DerivativeCardKeywords_64:Symphonie de l'Harmonie> » à votre main.<DerivativeCardKeywords_61:><DerivativeCardKeywords_62:>"
  },
  Skill_59476_Desc_15 = {
    Text = "Hamelin obtient <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Éveiller> : Au début du tour, place 1 «<DerivativeCardKeywords_64:Symphonie de l'Harmonie>» en main. Au début du tour, pour chaque Carte avec «Rondino» ou «Melodie Chargée», Hamelin obtient <Energy:[Energy:Arg2]> Aliemus. Lors du lancement de «Note de musique de l'Origine», pour chaque 2 Cartes d'instruction avec «Rondino» ou «Melodie Chargée» existantes, nombre de Dommages +1 <DerivativeCardKeywords_61:><DerivativeCardKeywords_62:>"
  },
  Skill_59476_EffectNameList = {Text = "Fureur"},
  Skill_59476_Name = {
    Text = "Cette chanson mérite des éloges"
  },
  Skill_59477_AwakerSkillBackgroundStory = {
    Text = "D'où vient la musique ? Des rites de dévotion, des chants des fermiers, des cris des primitifs, des chants des oiseaux au printemps, du vent dans les pins et des vagues, des tremblements de terre et des effondrements de montagnes... ou des murmures des dieux dans le chaos primordial"
  },
  Skill_59477_BattleDesc_0 = {
    Text = "Inflige aléatoirement [Arg3] fois <Damage:[Damage:Arg1]> points de <PunctureDamagewords:Dégâts Perçants>. Chaque coup : réduisez temporairement la <ExhaustionIconKeywords:Force> de la cible de [Exhaustion:Arg2] ; gagnez [Power:Arg2] de <PowerIconKeywords:Force Temporaire>. Choisissez 1 carte d'instruction non–<DepleteIconKeywords:Consommable> et non dérivée sans « <HuihuanaKeywords:Rondino> » ni « <XushiAKeywords:Melodie Chargée> » dans votre main pour ajouter « <HuihuanaKeywords:Rondino> ». Chaque fois qu'aucune carte ne peut être ajoutée, infligez à la place 3 points de dégâts supplémentaires"
  },
  Skill_59477_BattleDesc_2 = {
    Text = "Inflige aléatoirement [Arg3] fois <Damage:[Damage:Arg1]> points de <PunctureDamagewords:Dégâts Perçants>. Chaque coup : réduisez temporairement la <ExhaustionIconKeywords:Force> de la cible de [Exhaustion:Arg2] ; gagnez [Power:Arg2] de <PowerIconKeywords:Force Temporaire>. Choisissez 1 carte d'instruction non–<DepleteIconKeywords:Consommable> et non dérivée sans « <HuihuanaKeywords:Rondino> » ni « <XushiAKeywords:Melodie Chargée> » dans votre main pour ajouter « <HuihuanbKeywords:Rondino> ». Chaque fois qu'il n'y a pas de carte à ajouter, infligez plutôt 3 points de dégâts supplémentaires"
  },
  Skill_59477_Desc_0 = {
    Text = "Inflige aléatoirement 3 fois <Damage:[Damage:Arg1]> points de <PunctureDamagewords:Dégâts Perçants>, chaque fois en <TouquKeywords:volant> [Arg2] points de <ExhaustionIconKeywords:Force> temporaire à la cible. Choisissez 1 carte d'instruction non–<DepleteIconKeywords:Consommable> et non dérivée sans « <HuihuanaKeywords:Rondino> » ni « <XushiAKeywords:Melodie Chargée> » dans votre main pour ajouter « <HuihuanaKeywords:Rondino> ». Si aucune carte ne peut être ajoutée, infligez à la place 3 fois des dégâts supplémentaires"
  },
  Skill_59477_Desc_2 = {
    Text = "Inflige aléatoirement 3 fois <Damage:[Damage:Arg1]> points de <PunctureDamagewords:Dégâts Perçants>, chaque fois en <TouquKeywords:volant> [Arg2] points de <ExhaustionIconKeywords:Force> temporaire à la cible. Choisissez 1 carte d'instruction non–<DepleteIconKeywords:Consommable> et non dérivée dans votre main qui ne possède pas « <HuihuanaKeywords:Rondino> » ni « <XushiAKeywords:Melodie Chargée> » pour ajouter « <HuihuanaKeywords:Rondino> ». Chaque fois qu'il n'y a pas de carte à ajouter, infligez plutôt 3 fois supplémentaires de dégâts"
  },
