  Skill_61122_BattleDesc = {
    Text = "Considéré comme \"Frappe.\" Inflige <Damage:[Damage:Arg1]> dégâts. Ces dégâts bénéficient d'un bonus de force de 5x et déclenchent un effet de <BleedingIconKeywords:Bleeding> de 30 % sur la cible, restaurant [Arg3]% des HP perdus (<Heal:[Arg2]>). Après avoir été joué, il devient \"<DerivativeCardKeywords_65:Hilote>.\""
  },
  Skill_61122_Desc = {
    Text = "Considéré comme un \"Frappe\". Inflige <Damage:[Damage:Arg1]> points de dégâts, bénéficiant d'un bonus de 5x Pouvoir et déclenchant 30% <BleedingIconKeywords:Saignement> sur la cible, récupérant 15% de la Vie perdue. Après avoir joué, elle se transforme en \"<DerivativeCardKeywords_65:Hilote>\"."
