  Skill_61123_AwakerSkillBackgroundStory = {
    Text = "Chante, déesse ! Chante le destin de la fille de Délos :\n pleine de sang et de larmes, de rage et de désespoir.\n Sa haine est comme un feu ardent, tout consumant autour d'elle, et finalement,\n amenant ainsi sa propre mort"
  },
  Skill_61123_Desc_0 = {
    Text = "Helot : Enchaînée obtient <Energy:[Energy:Arg1]> points de fureur. <ExaltIconKeywords:réveil> : Ajoutez une carte « <DerivativeCardKeywords_65:Chaîne de sang> » à votre main, la carte d'instruction de Helot : Enchaînée obtient « <RetainIconKeywords:Garder> ». Au début du tour, le dommage de base de Helot : Enchaînée augmente de [Arg2]% dans ce combat."
  },
  Skill_61123_Desc_15 = {
    Text = "Helot : Enchaînée obtient <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Éveil> : Place une « <DerivativeCardKeywords_65:Chaîne de sang> » en main, et les Cartes d'instruction d'Helot : Enchaînée obtiennent « <RetainIconKeywords:Garder> ». Au début du tour, le Dommage de base d'Helot : Enchaînée +[Arg2]% pour ce combat. Après avoir déclenché l'Exaltation « Chaînes de restriction », accorde à chaque Carte d'instruction unique « Helot : Enchaînée » en main 35 charges de <TempPowerKeywords:Renforcement Temporaire>."
  },
  Skill_61123_EffectNameList = {
    Text = "Folie, augmentation des dégâts"
  },
