  Skill_70142_Desc = {
    Text = "Obtenez [Arg1] points de bouclier et accumulez 1 point supplémentaire d'« Énergie de l'Abîme »."
  },
  Skill_70142_Name = {Text = "Sommeil"},
  Skill_70286_Desc_1 = {
    Text = "<PVPWeaponKeywords:Roue du Destin> : À la fin du tour, augmente de [Arg1]% les Dommages, les soins et le Bouclier de toutes les «Compétences» du Porteur présentes dans la Main."
  },
  Skill_70286_Name_1 = {
    Text = "Trône de pierre bleue"
  },
  Skill_70299_AwakerSkillBackgroundStory = {
    Text = "Elle a poursuivi toute sa vie un but qui se trouve maintenant à portée de main. \nLa porte noire dégage une attraction mortelle. \nAvant d'ouvrir la porte, elle a imaginé 372 possibilités de vérité. \nAprès avoir ouvert la porte, il ne reste que la 373ème qu'elle ne veut pas admettre. \nSans choix, elle ne peut que tomber. \nQuelle malchance, elle-même et le monde entier."
  },
  Skill_70299_BattleDesc = {
    Text = "Les autres Corps éveillés gagnent <Energy:[Energy:Arg1]> Aliemus, infligent [Poison:Arg2] <plural value=\"[Poison:Arg2]\" singular=\"charge\" plural=\"charges\"> de <IntoxicationIconKeywords:Poison> à tous les ennemis, et augmentent temporairement l'Amplification de Dégâts de l'équipe de [Arg3]%."
  },
  Skill_70299_Desc = {
    Text = "Les autres Corps éveillés gagnent <Energy:[Energy:Arg1]> Aliemus, infligent [Poison:Arg2] <plural value=\"[Poison:Arg2]\" singular=\"charge\" plural=\"charges\"> de <IntoxicationIconKeywords:Poison> à tous les ennemis, et augmentent temporairement l'Amplification de Dégâts de l'équipe de [Arg3]%. « Forme Finale » : Piochez 3 Cartes supplémentaires, obtenez 3 Arithmetica, déclenchez 50% du <IntoxicationIconKeywords:Poison> sur tous les ennemis, et augmentez l'Aliemus de base de « Fusion · Dor » de 50, jusqu'à 3 fois."
  },
  Skill_70299_EffectNameList = {
    Text = "folie, empoisonnement, Dégâts puissants"
  },
  Skill_70299_Name = {
    Text = "Point Final, Porte de la Vérité et de l'Abîme"
  },
  Skill_70299_OverLimitUtlSkillDesc = {
    Text = "Les autres Corps éveillés gagnent <Energy:[Energy:Arg4]> Aliemus, infligent [Poison:Arg2] <plural value=\"[Poison:Arg2]\" singular=\"charge\" plural=\"charges\"> de <IntoxicationIconKeywords:Poison> à tous les ennemis, augmentent temporairement l'Amplification de Dégâts de l'équipe de [Arg3]%, et augmentent le <IntoxicationIconKeywords:Poison>, la <RetaliateIconKeywords:Contre-attaque> et le Dommage de base de tous les Corps éveillés de 10%. En Combat de Chef, obtenez une charge supplémentaire de « Finale »."
  },
  Skill_70299_PropertyNameList = {
    Text = "$GrowValue1,Puissance d'attaque*GrowValue2,$GrowValue3％"
  },
  Skill_70300_AwakerSkillBackgroundStory = {
    Text = "Lorsque le sporange écarlate se dilate sous la carapace mécanique, le résonateur en laiton tisse une matrice de défense en forme de nid d'abeille. \n Le réseau de pulsatiles mycéliens déchire l'espace, l'acide grave des inscriptions d'avertissement, tandis que le faisceau de désintégration des mémoires se réchauffe — toute chair qui touche la frontière finira par devenir un échantillon convulsant dans la cuve de culture."
  },
  Skill_70300_BattleDesc = {
    Text = "Obtenir <Block:[Block:Arg1]> points de bouclier. obtenir <Energy:[Energy:Arg2]> points d'aliemus"
  },
  Skill_70300_Desc = {
    Text = "Obtenir <Block:[Block:Arg1]> points de bouclier. « Fusion : Poupée » reçoit <Energy:[Energy:Arg2]> points d'aliemus."
  },
  Skill_70300_EffectNameList = {
    Text = "Bouclier, folie"
  },
  Skill_70300_Name = {Text = "Défense"},
  Skill_70300_PropertyNameList = {
    Text = "Défense *GrowValue1, $GrowValue2"
  },
  Skill_70301_AwakerSkillBackgroundStory = {
    Text = "Les pinces proviennent de son passé, de sa race, et incarnent une force qu'elle n'a jamais abandonnée. \nLorsque ces pinces transpercent la poitrine de l'ennemi, quel est donc le sens du sourire qui s'épanouit à ce moment ?"
  },
  Skill_70301_BattleDesc = {
    Text = "Causes <Damage:[Damage:Arg1]> points de dégâts. Gagne <Energy:[Energy:Arg2]> points de folie"
  },
  Skill_70301_Desc = {
    Text = "Inflige <Damage:[Damage:Arg1]> points de dégâts. « Fusion : Poupée » gagne <Energy:[Energy:Arg2]> points de folie."
  },
  Skill_70301_EffectNameList = {
    Text = "Dégâts, folie"
  },
  Skill_70301_Name = {Text = "Attaque"},
  Skill_70301_PropertyNameList = {
    Text = "Puissance d'attaque*GrowValue1,$GrowValue2"
  },
  Skill_70302_AwakerSkillBackgroundStory = {
    Text = "Elle s'est sacrifiée, échangeant sa chance de toucher la réalité. Quand elle retira sa main, son âme avait fondu comme de la cire."
  },
  Skill_70302_BattleDesc_0 = {
    Text = "« Fusion · Dor » gagne <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Éveiller> : En fin de tour, récupère <Heal:[Heal:Arg2]> PV et gagne <Energy:[Energy:Arg4]> Aliemus. « Forme Finale » : Ne récupère plus de PV ; déclenche à la place [Arg3]% de <IntoxicationIconKeywords:Poison> sur tous les ennemis."
  },
  Skill_70302_BattleDesc_15 = {
    Text = "« Fusion · Dor » gagne <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Éveiller> : Pour chaque charge de « Appel Final », Amplification de Dégâts +8%. « Fin du Néant » accorde à tous les Corps éveillés 30% d'Aliemus de base. En fin de tour, récupère <Heal:[Heal:Arg2]> PV et gagne <Energy:[Energy:Arg4]> Aliemus. « Forme Finale » : Ne récupère plus de PV, déclenche à la place [Arg3]% de <IntoxicationIconKeywords:Poison> sur tous les ennemis."
  },
  Skill_70302_Desc_0 = {
    Text = "« Fusion · Dor » obtient <Energy:[Energy:Arg1]> points de fureur. <ExaltIconKeywords:Éveiller> : à la fin du tour, restaurez <Heal:[Heal:Arg2]> points de PV et obtenez des points de fureur équivalents à votre recharge de fureur. « Forme Finale » : ne restaure plus de PV, mais déclenche un effet d'<IntoxicationIconKeywords:poison> de [Arg3] % sur tous les ennemis."
  },
  Skill_70302_Desc_15 = {
    Text = "« Fusion · Dor » gagne <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Éveiller> : Pour chaque charge de « Appel Final », Amplification de Dégâts +8%. « Fin du Néant » accorde à tous les Corps éveillés 30% d'Aliemus de base. En fin de tour, récupère <Heal:[Heal:Arg2]> PV et gagne de l'Aliemus égal à la Charge de fureur. « Forme Finale » : Ne récupère plus de PV, déclenche à la place [Arg3]% de <IntoxicationIconKeywords:Poison> sur tous les ennemis."
  },
  Skill_70302_EffectNameList = {
    Text = "Folie, récupération, taux de poison déclenché"
  },
  Skill_70302_Name = {
    Text = "Peste des âmes"
  },
  Skill_70302_PropertyNameList = {
    Text = "$GrowValue1, Constitution*GrowValue2,$GrowValue3％,"
  },
  Skill_70303_AwakerSkillBackgroundStory = {
    Text = "Si l'humanité marche déjà sur la route unidirectionnelle de l'annihilation, alors la pousser un peu serait-il une forme de miséricorde ?\n Lorsque la fin viendra en un instant, la souffrance se cristallisera également en un instant. \n Les gens n'auront qu'à s'accrocher à ceux qu'ils aiment, puis à accueillir ensemble le néant de l'anéantissement. \n Si à la fin il n'y a plus de souffrance, est-ce que cela compte comme atteindre le paradis ?"
  },
  Skill_70303_BattleDesc_0 = {
    Text = "Inflige des <RealDamage:Dégâts Fixes> égaux à 30% de leurs PV Max à tous les ennemis (minimum [Arg2]). Après utilisation, les compétences spécifiques de «Fusion · Dor» passent en «Forme Fin»."
  },
  Skill_70303_BattleDesc_3 = {
    Text = "Inflige des <RealDamage:Dégâts Fixes> égaux à 30% de leurs PV Max à tous les ennemis (minimum [Arg2]), restaurant 30% des Points de vie perdus (<Heal:[Heal:Arg3]>). Après utilisation, les compétences spécifiques de «Fusion · Dor» passent en «Forme Fin»."
  },
  Skill_70303_Desc_0 = {
    Text = "Inflige des <RealDamage:Dégâts Fixes> égaux à 25% des PV Max de chaque ennemi, avec un minimum de DGT égal à [Arg1]% de vos PV Max. Après utilisation, les compétences spécifiques de «Fusion · Dor» passent en «Forme Fin». L'effet de «Fin du Néant» ne s'active qu'une seule fois."
  },
  Skill_70303_Desc_3 = {
    Text = "Inflige des <RealDamage:Dégâts Fixes> égaux à 30% des PV Max de tous les ennemis. Ces DGT ne seront pas inférieurs à [Arg1]% de vos PV Max. Restaure 30% des Points de vie perdus. Après utilisation, les compétences spécifiques de «Fusion · Dor» passent en «Forme Fin». L'effet de «Fin du Néant» ne s'active qu'une seule fois."
  },
  Skill_70303_Name = {
    Text = "Fin du Néant"
  },
  Skill_70303_tempBattleDesc_1 = {
    Text = "Inflige des <RealDamage:Dégâts Fixes> égaux à 30% de leurs PV Max à tous les ennemis (minimum [Arg2]). Après utilisation, les compétences spécifiques de «Fusion · Dor» passent en «Forme Fin»."
  },
  Skill_70303_tempBattleDesc_2 = {
    Text = "Inflige des <RealDamage:Dégâts Fixes> égaux à 30% de leurs PV Max à tous les ennemis (minimum [Arg2]), restaurant 30% des Points de vie perdus (<Heal:[Heal:Arg3]>). Après utilisation, les compétences spécifiques de «Fusion · Dor» passent en «Forme Fin»."
  },
  Skill_70303_tempBattleDesc_3 = {
    Text = "Inflige des <FixedDamage:DGT Purs> à tous les ennemis égaux à 30% de leurs PV Max (minimum [Arg2]). Restaure 30% des Points de vie perdus ( <Heal:[Heal:Arg3]> ). Après utilisation, la compétence spécifique de «Fusion · Dor» passe en «Forme Fin». Tous les Éveilleurs gagnent 30% de Base Aliemus."
  },
  Skill_70304_AwakerSkillBackgroundStory = {
    Text = "Les mains de la poupée sont extrêmement habiles, le cœur de l'âme tenu entre elles comme un cube magique parfaitement docile.\nLa génie bienveillante serait ravie de vous offrir gratuitement une modification, même si les effets secondaires sont quelque peu exagérés."
