  Skill_78785_AwakerSkillBackgroundStory = {
    Text = "«S'il te plaît, dis-moi, qui es-tu vraiment ?» \n En posant cette question, elle éclata de rire. \n Le pauvre patient ne peut évidemment pas répondre, car sa mémoire a été altérée. Plus il cherche, plus il s'approche de l'existence terrifiante implantée dans sa mémoire—jusqu'à ce que sa cognition s'effondre complètement et qu'il se transforme en monstre."
  },
  Skill_78785_BattleDesc_0 = {
    Text = "Retirez toutes vos charges d'<AnalysisKeywords0:Empathie>, puis transformez-les en <D13AFKeyWord2:Trauma mental> ou <D13AFKeyWord1:Fixation phobique> sur tous les ennemis [Arg6] <plural value=\"[Arg6]\" singular=\"fois\" plural=\"fois\">. Infligez <Damage:[Damage:Arg1]> Dommages à tous les ennemis et obtenez <Posse:[Arg3]> Fragment de clé."
  },
