  Skill_83779_AwakerSkillBackgroundStory = {
    Text = "L'immense eau salée la dévorait, tout en la protégeant. \n Dans ce sentiment d'étouffement de la chute, elle percevait l'océan profond, s'y fondant. \n Un jour, l'océan sera complètement calme, chaque navire naviguant à la surface de la mer sera accordé à la paix. \n Elle attendait ce jour, ce « jour de la descente du Royaume Divin »."
  },
  Skill_83779_Desc_0 = {
    Text = "Kepsante reçoit <Energy:[Energy:Arg1]> points de folie. <ExaltIconKeywords:réveil> : gagne 1 tentacule, ajoute 2 cartes « <DerivativeCardKeywords_106:Piloter> » à votre main. Basculez en posture « Mer calme » pour obtenir <Block:[Block:Arg2]> points de bouclier, temps de recharge 3 tours."
  },
  Skill_83779_Desc_15 = {
    Text = "Corposant obtient <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Éveiller> : Obtient 1 Tentacule, ajoute 2 «<DerivativeCardKeywords_106:Piloter>» en main. Pour le premier «Châtiment du Tonnerre» et «Semaphore du Chaos» que Corposant joue chaque tour, place 1 «Piloter» supplémentaire en main. Effet de «<DerivativeCardKeywords_106:Piloter>» +50%. Après être passé en posture «Océan Calme», obtient <Block:[Block:Arg2]> Bouclier du personnage, avec un temps de recharge de 3 tours."
  },
  Skill_83779_EffectNameList = {
    Text = "Folie, bouclier"
  },
  Skill_83779_Name = {
    Text = "Sombré dans la mer lointaine"
  },
  Skill_83779_PropertyNameList = {
