  Skill_89776_AwakerSkillBackgroundStory = {
    Text = "«Frère, tu disais qu'en volant avec des ailes, on peut aller très haut, jusqu'où peut-on vraiment voler ? Peut-on atteindre les nuages et toucher la Lune et les étoiles ? »\n« Peut-être... que c'est possible ? Mais pour cela, nous aurons besoin d'une paire d'ailes très grandes et puissantes. »\nLa galaxie profonde et onirique ainsi que les constellations dans le manuscrit se reflètent dans le sommeil des deux enfants, se transformant en une graine de souhait, enfouie dans leur cœur."
  },
  Skill_89776_Desc_0 = {
    Text = "Castor obtient <Energy:[Energy:Arg1]> points d'Aliemus. <ExaltIconKeywords:Éveiller> : les Dommages infligés par Castor sont toujours des Critiques, et après avoir joué « <DerivativeCardKeywords_107:Plume Noire> », inflige [Corrosion:Arg2] couches de <Corrosion:Corrosion> à la cible, le Bouclier conservé est amélioré de 50%."
  },
  Skill_89776_Desc_15 = {
    Text = "Castor obtient <Energy:[Energy:Arg1]> points d'Aliemus. <ExaltIconKeywords:Éveiller> : Les Dommages de Castor sont toujours des coups critiques ; après avoir joué « <DerivativeCardKeywords_107:Plume Noire> », inflige [Corrosion:Arg2] <plural value=\"[Arg2]\" singular=\"charge\" plural=\"charges\"> de <Corrosion:Corrosion> à la cible. Obtient +50% de Bouclier du personnage en gardant les cartes Plume Noire en main en fin de tour. La première fois que « Plume Noire » est jouée chaque tour, inflige de la Corrosion égale au Talent « Plumes saintes de purification » à tous les ennemis, et les PV perdus lorsque la Corrosion est retirée passent de 300% à 500%."
  },
  Skill_89776_EffectNameList = {
    Text = "folie, Érosion"
  },
